public class Demo {
    public static void main(String[] args) {
        int x = 4;
        int y = 5;
        System.out.println(x + " , " + y);
        addTen(x, y);
        System.out.println(x + " , " + y);
    }

    static void addTen(int x, int y) {
        x = x + 10;
        y = y + 10;
    }
}

public class Demo2 {
    public static void main(String[] args) {
        Random r1 = new Random(4, 5);
        Random r2 = new Random(r1);
        addTen(r1);
        System.out.println(r1.x + " , " + r1.y);
        System.out.println(r2.x + " , " + r2.y);
    }

    static void addTen(Random r) {
        r.x = r.x + 10;
        r.y = r.y + 10;
    }
}

public class Demo {
    static void swap(Random a, Random b) {
        Random t = a;
        a = b;
        b = t;
        a.x = 100;
    }

    public static void main(String[] args) {
        Random r1 = new Random(1, 2);
        Random r2 = new Random(3, 4);
        swap(r1, r2);
        System.out.println(r1.x + " " + r2.x);
    }
}
